"""Reproduce evidence screening; curated findings are review questions, not error verdicts."""
import csv, hashlib, json
from pathlib import Path
from datetime import datetime, timezone
ROOT=Path(__file__).resolve().parents[4]
OUT=Path(__file__).parent
E=json.loads((ROOT/'projects/site/data/writer-enrichment.json').read_text())
D={int(p.stem):json.loads(p.read_text()) for p in (ROOT/'kb/research/writers/enrichment').glob('*.json')}
profiles=json.loads((ROOT/'projects/site/data/writer-profiles.json').read_text())
names={int(p['id']):p['name'] for p in profiles}
def name(i): return D[i].get('name',names.get(i,str(i)))
def paragraphs(i): return [p for s in E[str(i)].get('sections',[]) for p in s.get('paragraphs',[])]
def excerpt(i,contains):
    matches=[p for p in paragraphs(i) if contains in p]
    assert matches,(i,contains)
    return matches[0]
def sources(ids): return [{'writer_id':i, 'dossier':f'kb/research/writers/enrichment/{i}.json','sources':D[i]['sources']} for i in ids]
F=[]
def flag(ids,priority,kind,title,scope,claim,why,action,web=[]):
    F.append(dict(id=f'KBL-WA-{len(F)+1:03}',writer_ids=ids,names=[name(i) for i in ids],priority=priority,category=kind,title=title,status='open',scope=scope,exact_reader_text=claim,doubt=why,recommended_action=action,evidence=sources(ids),fresh_checks=web,independent=False))
flag([192,224],'first','identity','Neelam Saxena Chandra — two records','profile identity',[], 'The two dossiers identify the same bilingual writer and deliberately share a biography and book cards. The total 427 counts profile records, not 427 verified distinct people.', 'Confirm one identity and preferred canonical profile; reconcile poem ownership and redirects before any merge.')
flag([256,366],'first','identity','Neha Bhandarkar — two records','profile identity',[], 'Distinctive language/translation history and the same source/book evidence are reused across both records. Separate profile identity has not been justified.', 'Confirm duplicate identity with editor and map both sets of contributions before proposing a merge.')
flag([255,449],'first','identity_and_date','Tulika — probable duplicate and inconsistent award-date caution','active reader claim + profile identity',[excerpt(449,'2021 Pen')], 'Dossier255 flags captured2020 versus universityJanuary2021 and omits the date; profile449 states2021. Both depend on the same faculty page. A manuscript award cycle and presentation date might differ, but that has not been established.', 'Confirm both names refer to the same writer; obtain organizer record or explicitly attribute the date to the university consistently. Do not convert a manuscript into a published book.', ['Amity faculty page failed direct access (502); indexed university text again states January2021. This supports the attributed wording but does not reconcile the captured2020 record.'])
