flag([438],'follow-up','interpretation','Zahir Hossain Baidya — broad literary characterization','active reader interpretation',[excerpt(438,'rooted in the intensity')], 'The opening sentence generalizes about a writing practice from a very small sample. It is assistant interpretation, not a sourced biographical fact. The dated college byline is more concrete and should remain separate.', 'Consider removing the broad opening and shortening the poem commentary. Apply this editorial test to other inferred style/theme paragraphs; it is not a factual error verdict.')

manual_ids=sorted({i for f in F for i in f['writer_ids']})
rows=[]
for i,d in sorted(D.items()):
    ss=d.get('sources',[]); has_access=bool(ss) and all(s.get('access') for s in ss)
    opened=any('opened' in str(s.get('access','')).lower() for s in ss)
    index_only=has_access and not opened
    issues=[]
    if d['status']=='source_limited_local_draft': issues.append('source_limited')
    if index_only: issues.append('all_recorded_sources_indexed_only')
    if ss and not has_access: issues.append('source_access_not_recorded')
    ids=[f['id'] for f in F if i in f['writer_ids']]
    text=' '.join(paragraphs(i))
    rows.append(dict(writer_id=i,name=name(i),existing_status=d['status'],screening_flags=issues,curated_findings=ids,independent_factual_review='pending',coverage='metadata/evidence screening; see curated findings for manual assessment',narrative_words=len(text.split()),book_cards=len(E[str(i)].get('books',[])),source_count=len(ss),recorded_opened_source=opened,all_sources_index_only=index_only,dossier=f'kb/research/writers/enrichment/{i}.json',limitations=d.get('limitations',[]),source_access=[{'url':s.get('url'),'access':s.get('access','not_recorded')} for s in ss]))
counts=dict(profiles=len(rows),source_limited=sum('source_limited' in r['screening_flags'] for r in rows),all_sources_index_only=sum(r['all_sources_index_only'] for r in rows),missing_access=sum('source_access_not_recorded' in r['screening_flags'] for r in rows),evidence_followup_unique=sum(bool(r['screening_flags']) for r in rows),curated_findings=len(F),curated_profiles=len(manual_ids),narrative_words=sum(r['narrative_words'] for r in rows),book_cards=sum(r['book_cards'] for r in rows))
report=dict(audited_at=datetime.now(timezone.utc).isoformat(),scope='All427 records screened for evidence metadata; targeted manual claim review and selected primary-source rechecks. Not a fresh line-by-line external verification of all biographies or215book cards.',independent=False,public_content_changed=False,counts=counts,findings=F,profiles=rows)
(OUT/'findings.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
with (OUT/'profile-screening.csv').open('w') as fh:
    w=csv.writer(fh);w.writerow(['Writer ID','Name','Existing classification','Evidence follow-up','Specific findings','Independent factual review','Words','Book cards'])
    for r in rows:w.writerow([r['writer_id'],r['name'],r['existing_status'],'; '.join(r['screening_flags']),'; '.join(r['curated_findings']),'pending',r['narrative_words'],r['book_cards']])
def link(i):
    route={82:'poet-dokana',257:'poet-drink',337:'poet-kshanika'}.get(i,f'poet-{i}')
    return f'[{name(i)}](http://127.0.0.1:8771/{route}.html)'
md=['---', 'type: "Review"', 'title: "Writer enrichment — doubt checklist"', '---', '', '# Writer enrichment — doubt checklist','', '**Status: audit screening complete; factual/editorial review remains open.** No biographies, books, poems or profiles were changed by this audit. The enrichment loop remains paused.','',f"All **{counts['profiles']} profile records** were screened against their evidence metadata. This covers about **{counts['narrative_words']:,} words** of generated section text and **{counts['book_cards']} book cards**. It is not a fresh external verification of every sentence. Targeted findings below compare reader wording with dossiers, plus selected primary-source rechecks.",'','- **91 profiles** already have limited source evidence.','- **68 profiles** have only indexed/search evidence recorded for every cited source (67 are nevertheless classified source-checked). This does not mean the information is false.','- **3 earlier profiles** lack recorded source-access methods; do not count these as index-only.','- These groups overlap: **161 distinct profiles** need evidence follow-up on these screening criteria.','- Four possible duplicate pairs mean **427 records must not be described as 427 verified distinct writers**.','',f"There are **{len(F)} specific review items across {len(manual_ids)} profiles** below. “First” means resolve identity or material wording first; “Follow-up” means evidence, source structure or editorial judgment. Neither label asserts fabrication.",'','## Review first','']
for priority in ['first','follow-up']:
    if priority=='follow-up':md+=['','## Evidence and editorial follow-up','']
    for f in F:
        if f['priority']!=priority:continue
        md += [f"- [ ] **{f['id']} — {f['title']}**  ", f"  {f['doubt']} **Action:** {f['recommended_action']}  ", '  '+ ' · '.join(link(i) for i in f['writer_ids'])]
md += ['','## How to use the flags','','Do not remove every flagged paragraph automatically. Resolve a question using an identity-matched primary source, or soften/attribute the claim; omit it if useful support cannot be established. Record the evidence and decision before closing an item. Preserve captured originals and existing translator credits. No writer has received independent factual clearance from this audit.','','The automatically generated poem commentary is **literary interpretation**, not author-approved biography. Keep a short, clearly scoped reading of the poems; avoid treating poetic speakers as autobiographical or extrapolating a whole career from one poem. Consider shortening these passages during our page review. This audit did not re-read every poem.','','## Already contained uncertainties — do not confuse with active errors','','The existing dossiers correctly withhold several claims: conflicting birth years for writers161 and372; unconfirmed death notice for71; inflated award wording for258; current-employment assertions for218; Ma Yongbo’s outside biography for423. Urna Bose152’s second-prize wording and Ratnamala Swain254’s translation roles were already handled cautiously. Their captured originals still need provenance-aware review, but an omitted claim is not an error in the new narrative.','','## Evidence and coverage','','[Detailed findings and all427 screening records](findings.json) · [Compact all-profile checklist](profile-screening.csv) · [Fresh source rechecks](source-rechecks.json) · [Prior91 source-limited follow-ups](../ENRICHMENT-COMPLETION.md)','','The earlier batch “verification passed” refers to build, integrity, route and rendering checks. It does **not** establish factual truth, source independence or author approval. “Source-checked” means some external support was found; a repeated contributor biography and an author’s self-description can share the same original claim.','','Executor: current assistant, Anvesha research / Drishti self-review; independent=false. User requested doubts to be flagged, not publication or wholesale rewriting.']
(OUT/'REVIEW-CHECKLIST.md').write_text('\n'.join(md)+'\n')
print(json.dumps(counts,indent=2))
